    Bug 1831475 - Enable GloDa indexing of messages from multiple authors. r=john.bieling,mkmelin


    Instead of silently throwing an error and not indexing such messages, just use the first author provided in the 'From:' header.

    Differential Revision: https://phabricator.services.mozilla.com/D250408

diff --git a/mailnews/db/gloda/modules/GlodaFundAttr.sys.mjs b/mailnews/db/gloda/modules/GlodaFundAttr.sys.mjs
index fb1d1096554..011f93e7768 100644
--- a/mailnews/db/gloda/modules/GlodaFundAttr.sys.mjs
+++ b/mailnews/db/gloda/modules/GlodaFundAttr.sys.mjs
@@ -508,15 +508,14 @@ export var GlodaFundAttr = {
       )
     );

-    if (authorIdentities.length != 1) {
+    if (authorIdentities.length < 1) {
       throw new Gloda.BadItemContentsError(
         "Message with subject '" +
           aMsgHdr.mime2DecodedSubject +
           "' somehow lacks a valid author.  Bailing."
       );
     }
-    const authorIdentity = authorIdentities[0];
-    aGlodaMessage.from = authorIdentity;
+    aGlodaMessage.from = authorIdentities[0];

     // -- To, Cc, Bcc
     aGlodaMessage.to = toIdentities;
diff --git a/mailnews/db/gloda/test/unit/test_index_bad_messages.js b/mailnews/db/gloda/test/unit/test_index_bad_messages.js
index ee617e17785..cc64fa9ba29 100644
--- a/mailnews/db/gloda/test/unit/test_index_bad_messages.js
+++ b/mailnews/db/gloda/test/unit/test_index_bad_messages.js
@@ -14,9 +14,10 @@ var {
 } = ChromeUtils.importESModule(
   "resource://testing-common/gloda/GlodaTestHelper.sys.mjs"
 );
-var { configureGlodaIndexing } = ChromeUtils.importESModule(
-  "resource://testing-common/gloda/GlodaTestHelperFunctions.sys.mjs"
-);
+var { configureGlodaIndexing, waitForGlodaDBFlush } =
+  ChromeUtils.importESModule(
+    "resource://testing-common/gloda/GlodaTestHelperFunctions.sys.mjs"
+  );
 var { Gloda } = ChromeUtils.importESModule(
   "resource:///modules/gloda/GlodaPublic.sys.mjs"
 );
@@ -31,6 +32,7 @@ var { MessageInjection } = ChromeUtils.importESModule(
 );

 const GLODA_BAD_MESSAGE_ID = 2;
+const GLODA_FIRST_VALID_MESSAGE_ID = 32;

 var illegalMessageTemplates = [
   // -- Authors
@@ -40,12 +42,6 @@ var illegalMessageTemplates = [
       From: "",
     },
   },
-  {
-    name: "too many authors (> 1)",
-    clobberHeaders: {
-      From: "Tweedle Dee <dee@example.com>, Tweedle Dum <dum@example.com>",
-    },
-  },
 ];

 var messageInjection;
@@ -59,8 +55,35 @@ add_setup(function () {
 add_task(async function test_illegal_message_no_author() {
   await illegal_message(illegalMessageTemplates[0]);
 });
-add_task(async function test_illegal_message_too_many_authors() {
-  await illegal_message(illegalMessageTemplates[1]);
+
+/**
+ * Test that a message containing multiple authors does get indexed using only
+ * the first author.
+ */
+add_task(async function test_message_multiple_authors() {
+  const [msgSet] = await messageInjection.makeNewSetsInFolders(
+    [messageInjection.getInboxFolder()],
+    [
+      {
+        count: 1,
+        clobberHeaders: {
+          From: "Tweedle Dee <dee@example.com>, Tweedle Dum <dum@example.com>",
+        },
+      },
+    ]
+  );
+
+  await waitForGlodaIndexer();
+  Assert.ok(...assertExpectedMessagesIndexed([msgSet]));
+
+  await waitForGlodaDBFlush();
+  const msgHdr = msgSet.getMsgHdr(0);
+  Assert.greaterOrEqual(
+    msgHdr.getUint32Property("gloda-id"),
+    GLODA_FIRST_VALID_MESSAGE_ID
+  );
+
+  Assert.equal(Gloda.isMessageIndexed(msgHdr), true);
 });

